from collections import defaultdict

def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    def parse_amount(amount_str):
        if not isinstance(amount_str, str):
            raise ValueError("Amount must be a string")

        s = amount_str.strip()
        if not s:
            raise ValueError("Empty amount string")

        is_negative = s.startswith('-')
        s = s.lstrip('-')
        s = s.replace('$', '').replace(',', '')

        try:
            value = float(s)
        except ValueError:
            raise ValueError(f"Cannot parse amount: {amount_str}")

        return -value if is_negative else value

    customer_totals = defaultdict(float)
    customer_names = {}

    for row in rows:
        customer_name = row.get("customer", "")

        if not customer_name or not str(customer_name).strip():
            continue

        trimmed_name = str(customer_name).strip()
        lower_name = trimmed_name.lower()

        if lower_name not in customer_names:
            customer_names[lower_name] = trimmed_name

        amount_str = row.get("amount", "")
        try:
            amount = parse_amount(amount_str)
        except (ValueError, TypeError):
            continue

        customer_totals[lower_name] += amount

    results = []
    for lower_name, total in customer_totals.items():
        name = customer_names[lower_name]
        rounded_total = round(total, 2)
        results.append((name, rounded_total))

    results.sort(key=lambda x: (-x[1], x[0]))

    return results[:n]
